// ctxloom's bridge into opencode. GENERATED by ctxloom for this session and
// rewritten on every launch: do not edit. It fires the hook commands ctxloom
// registered (CONFIG.hooks, by opencode's own hook point): before a tool with
// THE HOOK WIRE, claude's PreToolUse (preToolUse), elsewhere with ctxloom's
// own hook wire, and reads the answer back, listens for the session
// owner's wake on a unix socket, and keeps a transcript of each root session
// ctxloom reads back as the session's memory.
import { spawn } from "node:child_process"
import { mkdirSync, renameSync, rmSync, writeFileSync } from "node:fs"
import { createServer } from "node:net"
import { join } from "node:path"
import { createInterface } from "node:readline"

const CONFIG = {"hooks":{"chat.message":[{"command":"ctxloom","args":["hook","mail-drain","--engine","opencode"],"timeout":5}],"session.created":[{"command":"ctxloom","args":["hook","session-bind","--engine","opencode"],"timeout":5}],"session.idle":[{"command":"ctxloom","args":["hook","next-step","--engine","opencode"],"timeout":5}],"tool.execute.after":[{"command":"ctxloom","args":["hook","skill-mates","--engine","opencode"],"matcher":"Skill","timeout":5},{"command":"fmt-edited","matcher":"Edit|Write|apply_patch"}],"tool.execute.before":[{"command":"ltk evaluate","matcher":"Bash"},{"command":"ltk evaluate","matcher":"Edit|Write|apply_patch"},{"command":"guard","matcher":"WebFetch"},{"command":"shell-only","matcher":"Bash"},{"command":"native-before"}]},"tools":{"apply_patch":{"name":"apply_patch"},"bash":{"name":"Bash"},"edit":{"name":"Edit","keys":{"filePath":"file_path","newString":"new_string","oldString":"old_string","replaceAll":"replace_all"}},"glob":{"name":"Glob"},"grep":{"name":"Grep","keys":{"include":"glob"}},"read":{"name":"Read","keys":{"filePath":"file_path"}},"skill":{"name":"Skill","keys":{"name":"skill"}},"task":{"name":"Task"},"todowrite":{"name":"TodoWrite"},"webfetch":{"name":"WebFetch"},"websearch":{"name":"WebSearch"},"write":{"name":"Write","keys":{"filePath":"file_path"}}},"wakeEnv":"CTXLOOM_OPENCODE_WAKE_SOCKET","transcript":{"env":"XDG_DATA_HOME","rel":"opencode/ctxloom"}}

// run spawns one hook (exec form with args, else one shell line) with the
// payload on stdin; it resolves to the hook's stdout, "" on any failure: a
// hook that cannot run never stops the session.
function run(hook, payload) {
  return new Promise((resolve) => {
    const argv = hook.args ? [hook.command, hook.args] : ["sh", ["-c", hook.command]]
    let child
    try {
      child = spawn(argv[0], argv[1], { stdio: ["pipe", "pipe", "ignore"] })
    } catch {
      return resolve("")
    }
    let out = ""
    const timer = setTimeout(() => child.kill("SIGKILL"), (hook.timeout || 60) * 1000)
    child.stdout.on("data", (b) => (out += b))
    child.on("error", () => resolve(""))
    child.on("close", (code) => {
      clearTimeout(timer)
      resolve(code === 0 ? out : "")
    })
    child.stdin.on("error", () => {})
    child.stdin.end(JSON.stringify(payload))
  })
}

// normalise is a tool call in claude's spelling (CONFIG.tools): its claude
// name, and a copy of its input with claude's keys. A tool the table does not
// list passes verbatim; opencode's own args are never touched.
function normalise(tool, args) {
  const t = CONFIG.tools[tool]
  if (!t) return { name: tool, input: args || {} }
  const input = {}
  for (const [k, v] of Object.entries(args || {})) input[(t.keys || {})[k] || k] = v
  return { name: t.name, input }
}

// nameList is a matcher claude reads as a list of exact names: only letters,
// digits, "_", "-", spaces, "," and "|".
const nameList = new RegExp("^[A-Za-z0-9_|, -]*$")

// matches is a hook's matcher against a tool's claude name, by claude's rule:
// none or "*" admits every tool; a name list (nameList) is exact; anything
// else is an unanchored regexp.
function matches(matcher, name) {
  if (!matcher || matcher === "*") return true
  if (nameList.test(matcher)) return matcher.split(new RegExp("[|,]")).map((m) => m.trim()).includes(name)
  try {
    return new RegExp(matcher).test(name)
  } catch {
    return false
  }
}

// denyReason is the reason of a PreToolUse deny, "" for every other answer:
// the hook wire's replies are a deny WITH a reason, or nothing. allow, ask, a
// reasonless deny, any other shape, and (by run) a failed hook all pass.
function denyReason(out) {
  let a
  try {
    a = JSON.parse(out)
  } catch {
    return ""
  }
  const h = (a && a.hookSpecificOutput) || {}
  return h.permissionDecision === "deny" && typeof h.permissionDecisionReason === "string" ? h.permissionDecisionReason : ""
}

// preToolUse fires the pre-tool hooks with the hook wire, claude's
// PreToolUse input, the call normalised to claude's spelling; it resolves to
// the first deny's reason, "" when every hook lets the call through.
async function preToolUse(input, args, transcript) {
  const call = normalise(input.tool, args)
  const payload = {
    session_id: input.sessionID,
    transcript_path: transcript,
    cwd: process.cwd(),
    hook_event_name: "PreToolUse",
    tool_name: call.name,
    tool_input: call.input,
    tool_use_id: input.callID,
  }
  for (const hook of CONFIG.hooks["tool.execute.before"] || []) {
    if (!matches(hook.matcher, call.name)) continue
    const reason = denyReason(await run(hook, payload))
    if (reason) return reason
  }
  return ""
}

// fire runs every hook registered on a hook point whose matcher admits the
// tool (by its claude name), in order, and folds their answers.
async function fire(point, fields) {
  const answer = { context: [], notice: [], block: false, reason: "" }
  const name = fields.tool ? normalise(fields.tool).name : ""
  for (const hook of CONFIG.hooks[point] || []) {
    if (hook.matcher && !matches(hook.matcher, name)) continue
    const out = (await run(hook, { event: point, cwd: process.cwd(), ...fields })).trim()
    if (!out) continue
    let a
    try {
      a = JSON.parse(out)
    } catch {
      continue
    }
    if (a.context) answer.context.push(a.context)
    if (a.notice) answer.notice.push(a.notice)
    if (a.block) {
      answer.block = true
      answer.reason = answer.reason || a.reason || "blocked by a ctxloom hook"
    }
  }
  return answer
}

// partID is an id opencode accepts for a part ctxloom adds ("prt" + an
// ascending time prefix, as opencode's own).
let counter = 0
function partID() {
  const t = ((BigInt(Date.now()) * 0x1000n + BigInt(++counter % 0x1000)) % (1n << 48n)).toString(16).padStart(12, "0")
  return "prt_" + t + Math.random().toString(36).slice(2, 16).padEnd(14, "0")
}

export const CtxloomBridge = async ({ client }) => {
  const children = new Set() // sub-agent sessions: no session hooks, no transcript
  const started = new Map() // root session -> its session_start context
  let current = "" // the root session a wake prompts

  const notify = (notices) => {
    for (const message of notices) client.tui.showToast({ body: { message, variant: "info" } }).catch(() => {})
  }
  const transcriptDir = () => {
    const base = process.env[CONFIG.transcript.env]
    return base ? join(base, CONFIG.transcript.rel) : ""
  }
  const transcriptPath = (sid) => (transcriptDir() ? join(transcriptDir(), sid + ".jsonl") : "")

  // start fires session_start once per root session this process sees:
  // created here (startup), or first prompted here after a resume.
  async function start(sid, source) {
    if (started.has(sid)) return
    started.set(sid, [])
    const a = await fire("session.created", { session: sid, source, transcript: transcriptPath(sid) })
    started.set(sid, a.context)
    notify(a.notice)
  }

  // record rewrites the session's transcript whole, atomically: its
  // session_start context first, then every message as opencode holds it.
  async function record(sid) {
    const file = transcriptPath(sid)
    if (!file) return
    const res = await client.session.messages({ path: { id: sid } }).catch(() => undefined)
    if (!res || !Array.isArray(res.data)) return
    const lines = [JSON.stringify({ ctxloom: { session: sid, context: started.get(sid) || [] } })]
    for (const m of res.data) lines.push(JSON.stringify(m))
    mkdirSync(transcriptDir(), { recursive: true })
    writeFileSync(file + ".tmp", lines.join("\n") + "\n")
    renameSync(file + ".tmp", file)
  }

  // wake prompts the current root session (one is created if there is
  // none) with the wake text; opencode queues it behind a busy turn. Its
  // turn_start hooks fire HERE, before the prompt exists: a wake they block
  // (a stale one, whose mail a typed turn already took) is never sent, so it
  // costs no turn and shows nothing; their context rides the prompt itself.
  const prefired = new Set()
  async function wake(text) {
    if (!current) {
      const res = await client.session.create({ body: {} }).catch(() => undefined)
      if (!res || !res.data) return
      current = res.data.id
      await start(current, "startup")
    }
    const a = await fire("chat.message", { session: current, prompt: text })
    notify(a.notice)
    if (a.block) return
    const parts = [{ type: "text", text }, ...a.context.map((c) => ({ type: "text", text: c, synthetic: true }))]
    prefired.add(text)
    await client.session.promptAsync({ path: { id: current }, body: { parts } }).catch(() => prefired.delete(text))
  }

  let server
  const socket = CONFIG.wakeEnv && process.env[CONFIG.wakeEnv]
  if (socket) {
    rmSync(socket, { force: true })
    server = createServer((conn) => {
      createInterface({ input: conn }).on("line", (line) => line && wake(line))
      conn.on("error", () => {})
    })
    server.listen(socket)
  }

  return {
    dispose: async () => {
      if (server) server.close()
    },
    event: async ({ event }) => {
      const p = event.properties || {}
      if (event.type === "session.created") {
        if (p.info.parentID) return void children.add(p.info.id)
        current = p.info.id
        await start(p.info.id, "startup")
      } else if (event.type === "session.idle" && !children.has(p.sessionID)) {
        // The transcript first: a turn_end hook reads it, and `opencode run`
        // exits at idle without waiting on this handler.
        await record(p.sessionID).catch(() => {})
        notify((await fire("session.idle", { session: p.sessionID, transcript: transcriptPath(p.sessionID) })).notice)
      }
    },
    "chat.message": async (input, output) => {
      const sid = input.sessionID
      if (children.has(sid)) return
      current = sid
      await start(sid, "resume")
      const prompt = output.parts.filter((x) => x.type === "text" && !x.synthetic).map((x) => x.text).join("\n")
      if (prefired.delete(prompt)) return // a wake: its hooks already fired
      const a = await fire("chat.message", { session: sid, prompt })
      notify(a.notice)
      if (a.block) throw new Error(a.reason)
      for (const text of a.context) {
        output.parts.push({ id: partID(), sessionID: sid, messageID: output.message.id, type: "text", text, synthetic: true })
      }
    },
    "experimental.chat.system.transform": async (input, output) => {
      for (const text of started.get(input.sessionID) || []) output.system.push(text)
    },
    "tool.execute.before": async (input, output) => {
      const reason = await preToolUse(input, output.args, transcriptPath(input.sessionID))
      if (reason) throw new Error(reason)
    },
    "tool.execute.after": async (input, output) => {
      const response = { title: output.title, output: output.output, metadata: output.metadata }
      const a = await fire("tool.execute.after", { session: input.sessionID, tool: input.tool, tool_input: input.args, tool_response: response })
      notify(a.notice)
      if (a.block) throw new Error(a.reason)
      for (const text of a.context) output.output += "\n\n" + text
    },
  }
}
